  if (vn > b) vn = b;
  const monate = [];
  const d = new Date(`${vn.slice(0, 7)}-01T12:00:00Z`);
  while (d.toISOString().slice(0, 7) <= b.slice(0, 7) && monate.length < 60) {
    monate.push(d.toISOString().slice(0, 7));
    d.setUTCMonth(d.getUTCMonth() + 1);
  }
  return { von: vn, bis: b, monate };
}

